css:
/* ===== 日光手记 · Geniestudio —— soft daylight notebook ===== */
body { font-size: 16px; line-height: 1.5; letter-spacing: -0.01em; }

/* 氛围层：粉彩洗涤漂浮在天空画布上 */
.aurora i { filter: blur(120px); }
.aurora i:nth-child(1) { background: #f1e6ff; opacity: .6; }
.aurora i:nth-child(2) { background: #d3f6e3; opacity: .55; }
.aurora i:nth-child(3) { background: #ffd1b8; opacity: .45; }

/* 顶栏：极简排版导航，无容器 */
header { background: transparent; backdrop-filter: none; -webkit-backdrop-filter: none; border-bottom: 0; padding: 28px 48px; }
header.scrolled { border-bottom-color: transparent; background: #ebf5ff; }
.brand h1 { font-family: var(--font-display); font-weight: 500; font-size: 22px; letter-spacing: -0.02em; color: #0a0d12; }
.brand h1 em { color: #0069e0; }
.brand .sub { font-size: 12px; letter-spacing: .02em; color: #93979f; }
nav { background: transparent; border: 0; padding: 0; gap: 4px; backdrop-filter: none; }
nav button { font-size: 16px; font-weight: 500; letter-spacing: -0.01em; color: #535862; padding: 10px 18px; }
nav button:hover { color: #0a0d12; }
nav button.active { background: #181d27; color: #ffffff; box-shadow: 0 1px 2px rgba(10,13,18,.8), 0 0 0 1px #0a0d12; }
#theme-switch { background: #fafdff; border: 0; color: #535862; border-radius: 9999px; }
#theme-switch:hover { border: 0; color: #0a0d12; }

main { max-width: 1200px; padding: 0 48px 120px; }

/* 落地页 */
#landing { max-width: 720px; gap: 24px; }
#landing .mark { border-radius: 28px; background: #f1e6ff; border: 0; box-shadow: none; color: #0a0d12; font-family: var(--font-display); font-weight: 500; }
#landing h2 { font-family: var(--font-display); font-weight: 500; font-size: clamp(32px, 4vw, 48px); line-height: 1.17; letter-spacing: -0.02em; color: #0a0d12; }
#landing p { font-size: 16px; color: #535862; max-width: 52ch; }

/* 按钮：炭黑胶囊是页面唯一的致密视觉锚点 */
.btn { border: 0; border-radius: 9999px; padding: 14px 32px; font-size: 15px; font-weight: 500; letter-spacing: -0.01em; background: #fafdff; color: #0a0d12; backdrop-filter: none; }
.btn:hover { border: 0; background: #ffffff; transform: translateY(-1px); }
.btn.primary { background: #181d27; color: #ffffff; font-weight: 500; box-shadow: 0 1px 2px rgba(10,13,18,.8), 0 0 0 1px #0a0d12; }
.btn.primary:hover { filter: brightness(1.12); box-shadow: 0 1px 2px rgba(10,13,18,.8), 0 0 0 1px #0a0d12, 0 10px 24px rgba(10,13,18,.2); }
.btn.ghost { background: transparent; color: #535862; }
.btn.ghost:hover { background: rgba(250,253,255,.7); color: #0a0d12; }

/* Hero：左对齐，超大紧排标题 */
.hero { grid-template-columns: minmax(0, 1.08fr) minmax(340px, .92fr); gap: 56px; padding: 72px 0 56px; min-height: 0; align-items: center; }
.hero > div:not(.sig):not(.nebula) { grid-column: 1; grid-row: 1; }
.hero .nebula { grid-column: 1 / -1; grid-row: 2; margin-top: 8px; }
.hello { color: #0069e0; font-size: 12px; font-weight: 600; letter-spacing: .08em; margin-bottom: 24px; }
.hello::before { width: 28px; height: 2px; border-radius: 2px; background: #0069e0; }
.hero-title { font-family: var(--font-display); font-weight: 500; font-size: clamp(56px, 7.2vw, 110px); line-height: 1.05; letter-spacing: -0.02em; color: #0a0d12; margin-bottom: 24px; }
.hero-title .hl { background: none; -webkit-background-clip: initial; background-clip: initial; color: #0069e0; }
.hero-essence { font-size: 18px; line-height: 1.33; letter-spacing: -0.01em; color: #535862; max-width: 56ch; }
.hero-title.long { font-weight: 500; letter-spacing: -0.01em; }
.hero-essence strong { color: #0069e0; font-weight: 500; }
.hero-actions .btn { padding: 16px 36px; font-size: 16px; }

/* 主题星云：漂浮的粉彩胶囊 */
.nebula { height: 340px; }
.neb-tag { border: 0; padding: 10px 20px; font-size: 14px; font-weight: 500; letter-spacing: -0.01em; color: #0a0d12; background: #fafdff; box-shadow: 0 14px 20px 4px rgba(4,69,144,.08); backdrop-filter: none; }
.neb-tag:nth-child(3n+1) { background: #f1e6ff; }
.neb-tag:nth-child(3n+2) { background: #d3f6e3; }
.neb-tag:nth-child(3n) { background: #cce7ff; }
.neb-tag:hover { border: 0; color: #0069e0; }
.neb-tag b { color: #0069e0; font-weight: 600; }

/* 统计卡：粉彩洗涤 nth-child 轮换，文字用 Ink */
.stat-row { gap: 24px; margin-bottom: 76px; align-items: start; }
.stat { border: 0; border-radius: 32px; padding: 32px; background: #fafdff; backdrop-filter: none; box-shadow: none; }
.stat:nth-child(1) { transform: translateY(0) !important; }
.stat:nth-child(2) { transform: translateY(28px) !important; }
.stat:nth-child(3) { transform: translateY(12px) !important; }
.stat:nth-child(4) { transform: translateY(40px) !important; }
.stat:nth-child(4n+1) { background: #f1e6ff; }
.stat:nth-child(4n+2) { background: #d3f6e3; }
.stat:nth-child(4n+3) { background: #ffe0cc; }
.stat:nth-child(4n+4) { background: #cce7ff; }
.stat:hover { border: 0; }
.stat .num { font-family: var(--font-num); font-size: 48px; font-weight: 500; letter-spacing: -0.02em; color: #0a0d12; transform: none; }
.stat .label { font-size: 14px; letter-spacing: -0.01em; color: rgba(10,13,18,.62); margin-top: 12px; transform: none; }
.stat .spark { display: none; }

/* 面板：无边框无阴影，靠底色差与 32px 圆角定义 */
.dash-grid { gap: 24px; }
.rail { gap: 24px; }
.panel { background: #fafdff; border: 0; border-radius: 32px; padding: 40px; backdrop-filter: none; box-shadow: none; }
.panel:hover { border: 0; }
.panel:has(.persona-md) {
  border: 3px solid transparent;
  background:
    linear-gradient(#fafdff, #fafdff) padding-box,
    linear-gradient(115deg, rgb(71,157,255) 11.43%, rgb(0,105,224) 78.2%) border-box;
}
.panel h3 { font-family: var(--font-display); font-size: 24px; font-weight: 500; letter-spacing: -0.48px; color: #0a0d12; margin-bottom: 24px; }
.panel h3::after { display: none; }

.persona-md h1, .persona-md h2 { font-family: var(--font-display); font-weight: 500; font-size: 20px; letter-spacing: -0.01em; color: #0a0d12; }
.persona-md p, .persona-md li { font-size: 15px; color: #535862; }
.persona-md strong { color: #0069e0; font-weight: 600; }
.persona-md blockquote { border-left: 3px solid #0069e0; color: #535862; }

.tag-bar .track { height: 8px; background: rgba(10,13,18,.07); border-radius: 999px; }
.tag-bar .fill { background: linear-gradient(90deg, rgb(71,157,255), rgb(0,105,224)); border-radius: 999px; }
.tag-bar .count { color: #93979f; }
.material-item { border-bottom-color: rgba(10,13,18,.08); }
.mini-plan { border-bottom-color: rgba(10,13,18,.08); }
.mini-plan .mp-t { font-size: 15px; font-weight: 500; color: #0a0d12; }
.mini-plan:hover .mp-t { color: #0069e0; }
.mini-plan .mp-bar { height: 6px; background: rgba(10,13,18,.07); border-radius: 999px; }
.mini-plan .mp-fill { background: #0069e0; border-radius: 999px; }

/* 知识卡片 */
.toolbar { margin: 32px 0 28px; gap: 12px; }
.chip { border: 0; background: #fafdff; color: #535862; border-radius: 9999px; padding: 8px 16px; font-size: 14px; backdrop-filter: none; }
.chip:hover { color: #0a0d12; background: #ffffff; transform: none; }
.chip.active { background: #181d27; color: #ffffff; box-shadow: 0 1px 2px rgba(10,13,18,.8), 0 0 0 1px #0a0d12; }
.search-box { border: 0; background: #fafdff; border-radius: 16px; padding: 12px 20px; font-size: 14px; backdrop-filter: none; }
.search-box:focus { border: 0; box-shadow: 0 0 0 2px #0069e0; }
.card-grid { gap: 24px; }
.kcard { border: 0; border-radius: 32px; padding: 40px; background: #fafdff; backdrop-filter: none; box-shadow: none; transform: none !important; }
.kcard:nth-child(4n+1) { background: #f1e6ff; }
.kcard:nth-child(4n+2) { background: #d3f6e3; }
.kcard:nth-child(4n+3) { background: #ffe0cc; }
.kcard:nth-child(4n+4) { background: #cce7ff; }
.kcard:hover { border: 0; box-shadow: 0 14px 20px 4px rgba(4,69,144,.1); transform: translateY(-3px) !important; }
.kcard .ctitle { font-family: var(--font-display); font-weight: 500; font-size: 20px; line-height: 1.4; letter-spacing: -0.02em; color: #0a0d12; transform: none; }
.kcard .cmeta { color: rgba(10,13,18,.52); transform: none; }
.kcard .csummary { font-size: 14px; line-height: 1.5; color: rgba(10,13,18,.68); transform: none; }
.kcard .ctags { transform: none; }
.mini-tag { background: #cce7ff; color: #0a0d12; border-radius: 9999px; font-size: 12px; font-weight: 500; letter-spacing: -0.01em; padding: 4px 12px; }
.kcard .mini-tag { background: rgba(255,255,255,.62); }

/* 弹窗 */
#modal-mask { background: rgba(10,13,18,.32); }
#modal { background: #fafdff; border: 0; border-radius: 32px; padding: 40px 48px; box-shadow: 0 24px 60px rgba(4,69,144,.18); }
#modal h2 { font-family: var(--font-display); font-weight: 500; font-size: 32px; line-height: 1.25; letter-spacing: -0.64px; color: #0a0d12; }
#modal .mmeta { color: #93979f; font-size: 14px; margin-bottom: 24px; }
#modal .mmeta > span:first-child { color: #0a0d12; font-size: 16px; font-weight: 500; letter-spacing: -0.01em; }
#modal .mmeta a { color: #0069e0; }
#modal .mbody { border-top: 1px solid rgba(10,13,18,.1); padding-top: 24px; }
.mbody p, .mbody li { font-size: 16px; line-height: 1.5; }
.mbody h2 { color: #0069e0 !important; font-size: 16px !important; font-weight: 600; letter-spacing: -0.01em !important; }
.mbody p, .mbody li { color: #535862; }
#modal .edit-area { background: #f6f7f8; border: 0; border-radius: 16px; color: #0a0d12; }
#modal .edit-area:focus { box-shadow: 0 0 0 2px #0069e0; }

/* 规划页 */
.plan-list { gap: 24px; margin-top: 32px; }
.plan-card { border: 0; border-radius: 32px; padding: 40px; background: #fafdff; backdrop-filter: none; box-shadow: none; }
.plan-card:hover { border: 0; }
.plan-head .ptitle { font-family: var(--font-display); font-weight: 500; font-size: 24px; letter-spacing: -0.48px; color: #0a0d12; }
.status-badge { border: 0; background: #f6f7f8; color: #535862; border-radius: 9999px; font-size: 12px; font-weight: 500; letter-spacing: -0.01em; padding: 5px 14px; }
.status-badge.active { background: #d3f6e3; color: #0a0d12; }
.plan-goal { font-size: 15px; color: #535862; }
.plan-meta, .progress-num { color: #93979f; }
.progress-track { height: 8px; background: rgba(10,13,18,.07); border-radius: 999px; }
.progress-fill { background: linear-gradient(90deg, rgb(71,157,255), rgb(0,105,224)); border-radius: 999px; }
.task { font-size: 16px; font-weight: 500; letter-spacing: -0.01em; color: #0a0d12; background: #ffffff; border: 0; border-radius: 16px; padding: 14px 18px; margin-bottom: 8px; align-items: center; }
.task:last-child { margin-bottom: 0; }
.task input[type="checkbox"] { width: 20px; height: 20px; border-radius: 999px; border-color: #93979f; margin-top: 0; }
.task input[type="checkbox"]:checked { background: #181d27; border-color: #181d27; }
.task input[type="checkbox"]:checked::after { color: #ffffff; }
.plan-basis { border-top-color: rgba(10,13,18,.08); color: #93979f; }

/* ===== 洞察页：双极量尺 / 框架墙 / 红线盲区 / 修正史 / 热力图 ===== */
.insight-grid { gap: 24px; margin-top: 32px; }
.bipolar { gap: 24px; }
.bp-row .bp-ends { font-size: 14px; margin-bottom: 10px; }
.bp-row .bp-ends b { font-weight: 500; color: #0a0d12; }
.bp-row .bp-ends .bp-val { color: #0069e0; font-weight: 600; }
.bp-track { height: 10px; border-radius: 999px; background: rgba(10,13,18,.07); }
.bp-fill { border-radius: 999px; background: linear-gradient(90deg, rgb(71,157,255), rgb(0,105,224)); }
.bp-thumb { width: 18px; height: 18px; background: #ffffff; border: 3px solid #0069e0; box-shadow: 0 2px 6px rgba(4,69,144,.2); }
/* 框架墙：便签式轻微错位，±1deg 内旋转 */
.fw-wall { gap: 18px; padding: 8px 2px; }
.fw-card { border: 0; border-radius: 24px; background: #ffffff; padding: 28px; backdrop-filter: none; box-shadow: 0 14px 20px 4px rgba(4,69,144,.08); }
.fw-card:nth-child(3n+1) { transform: rotate(-.7deg) translateY(6px); background: #f1e6ff; }
.fw-card:nth-child(3n+2) { transform: rotate(.5deg); }
.fw-card:nth-child(3n) { transform: rotate(-.4deg) translateY(12px); background: #d3f6e3; }
.fw-card:hover { border: 0; transform: rotate(0deg) translateY(-3px); box-shadow: 0 14px 20px 4px rgba(4,69,144,.1); }
.fw-card .fw-name { font-weight: 500; font-size: 17px; letter-spacing: -0.01em; color: #0a0d12; }
.fw-card .fw-desc { font-size: 14px; color: #535862; margin-top: 10px; line-height: 1.6; }
.fw-card .fw-links a { color: #0069e0; font-size: 12px; }
.red-item { border-left: 0; border-radius: 16px; background: #ffe9e4; color: #0a0d12; padding: 12px 18px; font-size: 14px; }
.gap-item { border-left: 0; border-radius: 16px; background: #cce7ff; color: rgba(10,13,18,.72); padding: 12px 18px; font-size: 14px; }
.corr-item { border-bottom-color: rgba(10,13,18,.08); color: #535862; font-size: 14px; padding: 12px 0; }
.hm-cell { width: 14px; height: 14px; border-radius: 5px; }
.hm-legend { color: #93979f; margin-top: 14px; }
.insight-empty { color: #93979f; font-size: 15px; }

/* 图谱 / 时间线 */
#graph-box { border: 0; border-radius: 32px; background: #fafdff; backdrop-filter: none; box-shadow: none; }
.tl::before { width: 3px; left: 7px; background: #cce7ff; border-radius: 3px; }
.tl-month::before { width: 11px; height: 11px; left: -27px; background: #0069e0; box-shadow: 0 0 0 6px rgba(0,105,224,.15); }
.tl-month .mname { font-family: var(--font-display); font-weight: 500; font-size: 24px; letter-spacing: -0.48px; color: #0a0d12; }
.tl-item { border: 0; border-radius: 24px; background: #fafdff; padding: 20px 24px; backdrop-filter: none; }
.tl-item:hover { border: 0; transform: none; background: #ffffff; box-shadow: 0 14px 20px 4px rgba(4,69,144,.08); }
.tl-item .t { font-weight: 500; font-size: 15px; color: #0a0d12; }
.tl-item .d { color: #93979f; }

/* 导入按钮 / 拖拽遮罩 */
#btn-import { background: #fafdff; border: 0; color: #535862; border-radius: 9999px; padding: 9px 18px; font-size: 13px; font-weight: 500; }
#btn-import:hover { border: 0; color: #0a0d12; background: #ffffff; }
#drop-mask { background: rgba(235,245,255,.86); }
#drop-mask .drop-inner { border: 2px dashed #0069e0; border-radius: 32px; background: rgba(250,253,255,.7); padding: 56px 72px; }
#drop-mask b { color: #0a0d12; font-weight: 500; letter-spacing: -0.01em; }
#drop-mask span { color: #535862; }

/* 状态栏 / 通知 */
#status-bar { background: rgba(235,245,255,.92); border-top: 0; color: #93979f; }
#status-bar .ok { color: #0069e0; }
#toast { background: #181d27; color: #ffffff; border: 0; border-radius: 9999px; box-shadow: 0 8px 24px rgba(10,13,18,.25); }

/* 动效：快起缓落 */
.reveal { transition: opacity .6s cubic-bezier(.16,1,.3,1), transform .6s cubic-bezier(.16,1,.3,1); }

/* ---- 签名视觉：鸢尾渐变描边画框，把星云装进去 ---- */
.nebula {
  border: 3px solid transparent; border-radius: 48px; padding: 14px;
  background:
    linear-gradient(rgba(250,253,255,.72), rgba(250,253,255,.72)) padding-box,
    linear-gradient(115deg, rgba(71,157,255,.95), rgba(0,105,224,.30) 45%, rgba(241,230,255,.9)) border-box;
  box-shadow: 0 24px 48px rgba(4,69,144,.08);
}


/* 签名：大脑神经网络 —— 独占 hero 右列，完整露出，不被任何元素遮挡 */
.sig { display: block; grid-column: 2; grid-row: 1; width: 100%; height: 100%; min-height: 420px; align-self: stretch; justify-self: center; pointer-events: none; }
.sig canvas { margin: 0 auto; }

/* 移动端兜底：收回双栏 hero、错位与旋转 */
@media (max-width: 960px) {
  .hero { grid-template-columns: 1fr; gap: 24px; padding: 48px 0 40px; }
  .sig { grid-column: 1; grid-row: 1; height: 300px; min-height: 0; }
  .hero > div:not(.sig):not(.nebula) { grid-column: 1; grid-row: 2; }
  .hero .nebula { grid-column: 1; grid-row: 3; margin-top: 0; }
  .stat-row { margin-bottom: 24px; }
  .stat:nth-child(n) { transform: none !important; }
  .fw-card:nth-child(n) { transform: none; }
}
